 static AgentMove AiMove(MatchEngine g,FreezeMageAgent ai=null){return (ai??new FreezeMageAgent()).Choose(AgentBridge.Observe(g,0));}
 static void FreezeMageAi(){
  var deck=FreezeMageDeck.Create(catalog);Check(deck.Count==30&&deck.ClassId=="MAGE"&&deck.Cards.Keys.All(k=>matchRules.Supports(catalog.Card(k))),"Classic freeze deck is complete and supported");Check(DeckCode.Decode(catalog,DeckCode.Encode(catalog,deck),deck.PoolId).Cards.Count==17,"Freeze deck code roundtrip");
  var g=new MatchEngine(catalog,deck,matchRules.TrainingDeck("WARLOCK"),3,startingSeat:1);var ai=new FreezeMageAgent();var view=AgentBridge.Observe(g,0);Check(!view.CanAct&&ai.Choose(view)==null,"No action before mulligan");Check(g.Mulligan(0,ai.Mulligan(view)).Success&&g.Mulligan(1,new int[0]).Success&&g.Players[1].Mana==1&&!g.TestMode,"AI uses normal opening and no test tools");Check(!g.TestTakeCard(1,g.Players[1].Deck[0]).Success,"No AI test draw tool");
  g=Game();g.Players[1].Health=7;g.Players[0].Mana=3;int bolt=Hand(g,"CS2_024"),lance=Hand(g,"CS2_031");var move=AiMove(g,ai);Check(move.Source==bolt&&move.Target.Hero,"Lethal frostbolt before unfrozen lance");Check(AgentBridge.Execute(g,0,move).Success,"Chosen frostbolt is legal");move=AiMove(g);Check(move.Source==lance&&AgentBridge.Execute(g,0,move).Success&&g.Winner==0,"Lance completes seven damage lethal");
  g=Game();g.Players[1].Health=4;g.Players[0].Mana=1;Hand(g,"CS2_031");Check(AiMove(g).Kind=="end","Unfrozen lance is not four damage");
  g=Game();g.Players[1].Health=8;g.Players[1].Frozen=true;g.Players[0].Mana=2;Hand(g,"CS2_031");Hand(g,"CS2_031");Check(AgentBridge.Execute(g,0,AiMove(g)).Success&&AgentBridge.Execute(g,0,AiMove(g)).Success&&g.Winner==0,"Frozen double lance lethal");
  g=Game();g.Players[1].Health=9;g.Players[0].Mana=5;Hand(g,"EX1_012");Hand(g,"CS2_024");Hand(g,"CS2_031");for(int n=0;n<3&&!g.Finished;n++)Check(AgentBridge.Execute(g,0,AiMove(g)).Success,"Spellpower combo legal step");Check(g.Winner==0,"Thalnos incorporated into exact lethal");
  g=Game();g.Players[1].Health=6;g.Players[0].Mana=3;int coin=Hand(g,"GAME_COIN"),fire=Hand(g,"CS2_029");Check(AiMove(g).Source==coin,"Coin enables lethal fireball");AgentBridge.Execute(g,0,AiMove(g));Check(AiMove(g).Source==fire&&AgentBridge.Execute(g,0,AiMove(g)).Success&&g.Finished,"Coin lethal replanned");
  g=Game();g.Players[1].Health=4;g.Players[1].Armor=10;Hand(g,"CS2_029");Check(AiMove(g).Kind=="power","Armor included, preserves lone fireball");
  g=Game();g.Players[0].Health=6;g.Summon(1,"VAN_CS2_182");g.Summon(1,"VAN_CS2_182");g.Players[0].Mana=5;int doom=Hand(g,"NEW1_021"),nova=Hand(g,"CS2_026");move=AiMove(g);Check(move.Source==doom||move.Source==nova,"Doom nova plan chooses a combo card");int second=move.Source==doom?nova:doom;AgentBridge.Execute(g,0,move);Check(AiMove(g).Source==second,"Doom nova plan completes both parts");AgentBridge.Execute(g,0,AiMove(g));g.EndTurn();g.EndTurn();Check(g.Players.All(p=>p.Board.Count==0),"Doom nova actual clear resolves");
  g=Game();Hand(g,"CS2_032");Check(AiMove(g).Kind!="play","No flamestrike on empty board");g.Summon(1,"VAN_CS2_182").DamageTaken=1;g.Summon(1,"VAN_CS2_182").DamageTaken=1;Check(AiMove(g).Key=="CS2_032","Flamestrike selects useful clear");
  g=Game();var unit=g.Summon(1,"VAN_CS2_182");unit.Frozen=true;Hand(g,"CS2_026");Check(AiMove(g).Kind!="play","No redundant freeze");
  g=Game();g.Players[0].Health=5;g.Summon(1,"VAN_CS2_182");Hand(g,"EX1_561");move=AiMove(g);Check(move.Key=="EX1_561"&&move.Target.Seat==0,"Alexstrasza defensive heal under lethal threat");
  g=Game();Hand(g,"EX1_561");move=AiMove(g);Check(move.Key=="EX1_561"&&move.Target.Seat==1,"Alexstrasza offensively sets healthy enemy to fifteen");
  g=Game();g.Players[0].Health=3;g.Summon(1,"VAN_CS2_182");int block=Hand(g,"EX1_295");Hand(g,"CS2_023");Check(AiMove(g).Source==block,"Ice block prioritized over draw in danger");g.Play(0,block);Hand(g,"EX1_295");Check(!AgentBridge.Observe(g,0).Moves.Any(m=>m.Key=="EX1_295"),"Own duplicate secret filtered legally");
  g=Game();var acolyte=g.Summon(0,"VAN_EX1_007");move=AiMove(g);Check(move.Kind=="power"&&move.Target.UnitId==acolyte.Id,"Pings own acolyte to draw safely");
  g=Game();var own=g.Summon(0,"VAN_CS2_182");own.SummonTurn=0;g.Summon(1,"VAN_CS2_179");Check(!AgentBridge.Observe(g,0).Moves.Any(m=>m.Kind=="attack"&&m.Target.Hero),"Attacks respect taunt");
  g=Game();Hand(g,"CS2_029");Hand(g,"CS2_024",1);view=AgentBridge.Observe(g,0);string json=JsonData.Serializer().Serialize(view);Check(!json.Contains("VAN_CS2_024")&&!json.Contains("Seed")&&!json.Contains("DeckPreview")&&!json.Contains("Catalog"),"Agent view excludes opponent cards, seed and deck order");view.Self.Board=new AgentUnit[0];view.Hand[0].Cost=99;Check(g.HandCost(0,g.Players[0].Hand[0])==4,"Observation detached from authority");var before=AiMove(g);g.Players[1].Hand.Clear();Hand(g,"EX1_279",1);g.Players[1].Deck.Reverse();var after=AiMove(g);Check(before.Kind==after.Kind&&before.Source==after.Source,"Hidden identities and order cannot change decision");
  g.ArmSecret(1,new HandCard{Id=id++,CardId="VAN_EX1_287"});string unknown=JsonData.Serializer().Serialize(AgentBridge.Observe(g,0));g.DestroySecrets(1);g.ArmSecret(1,new HandCard{Id=id++,CardId="VAN_EX1_295"});Check(unknown==JsonData.Serializer().Serialize(AgentBridge.Observe(g,0)),"Enemy secret identities are absent, equal public situations are identical");
  g.Players[1].SecretImmuneTurn=g.Turn;Check(!AgentBridge.Observe(g,0).Moves.Any(m=>m.Target!=null&&m.Target.Seat==1&&m.Target.Hero),"Replans without burning into active ice block immunity");
  g=Game();g.Active=1;Check(AiMove(g)==null&&!AgentBridge.Execute(g,0,new AgentMove{Kind="end"}).Success&&g.Active==1,"Cannot operate or end opponent turn");
  g=Game();for(int n=0;n<10;n++)Hand(g,n%2==0?"CS2_031":"CS2_024");g.Players[1].Armor=100;var watch=Stopwatch.StartNew();AiMove(g,ai);watch.Stop();Check(ai.LastSearchNodes<=FreezeMageAgent.SearchNodeLimit&&watch.ElapsedMilliseconds<1000,"Search bounded in nodes and time");
  for(int seed=0;seed<3;seed++){
   var game=new MatchEngine(catalog,deck,deck,seed);for(int seat=0;seat<2;seat++)Check(game.Mulligan(seat,ai.Mulligan(AgentBridge.Observe(game,seat))).Success,"AI mulligan in full game");int actions=0;while(!game.Finished&&game.Turn<100&&actions<1600){int seat=game.Active;var action=ai.Choose(AgentBridge.Observe(game,seat));var result=AgentBridge.Execute(game,seat,action);if(!result.Success)throw new Exception("AI illegal action "+action.Kind+"/"+action.Key+": "+result.Message);actions++;}Check(game.Finished&&actions<1600,"Complete real-rules freeze mirror without loops or illegal moves");
  }
  // The visible position from the lost Zoo game: two health, no Ice Block,
  // 3/2 divine shield + 1/1 + 1/3 + 2/1. Freeze the actual lethal attacker.
  g=Game();g.Players[0].Health=2;g.Players[0].Mana=8;var scarlet=g.Summon(1,"VAN_EX1_020");g.Summon(1,"VAN_EX1_008").Shield=false;g.Summon(1,"VAN_CS2_065");g.Summon(1,"VAN_EX1_004");Hand(g,"CS2_029");Hand(g,"CS2_031");Hand(g,"NEW1_021");
  for(int n=0;n<5;n++){move=AiMove(g,ai);if(move.Kind=="end")break;Check(AgentBridge.Execute(g,0,move).Success,"Zoo survival sequence action legal");}
  Check(scarlet.Frozen&&g.Players[1].Board.Where(u=>!u.Frozen).Sum(u=>g.AttackValue(u))<g.Players[0].Health,"Survival plan freezes three attack and leaves no visible lethal");Check(ai.LastDefenseNodes<=FreezeMageDefense.NodeLimit,"Defense search bounded");
  g=Game();g.Players[0].Health=4;g.Players[0].Mana=6;var shield=g.Summon(1,"VAN_EX1_020");g.Summon(1,"VAN_CS2_065");Hand(g,"CS2_029");
  move=AiMove(g);Check(move.Kind=="power"&&move.Target.UnitId==shield.Id,"Break divine shield before fireball instead of wasting fireball on shield");AgentBridge.Execute(g,0,move);Check(AiMove(g).Key=="CS2_029"&&AiMove(g).Target.UnitId==shield.Id,"Fireball follows shield break on dangerous target");
  g=Game();g.Players[0].Health=3;Hand(g,"EX1_279");Check(AiMove(g).Kind=="power"&&AiMove(g).Target.Hero,"No false danger on empty enemy board at three health");
  g=Game();g.Players[0].Deck.Clear();g.Players[0].Deck.AddRange(new[]{"VAN_CS2_031","VAN_EX1_279","VAN_CS2_027"});g.Players[1].Health=14;Hand(g,"CS2_023");Hand(g,"EX1_279");Hand(g,"CS2_024");Hand(g,"CS2_031");Check(AiMove(g).Key!="CS2_023","Preserve deck when known burn already suffices");
  g=Game();g.Players[0].Deck.Clear();g.Players[0].Fatigue=2;Hand(g,"CS2_023");var ownPain=g.Summon(0,"VAN_EX1_007");move=AiMove(g);Check(move.Key!="CS2_023"&&(move.Target==null||move.Target.UnitId!=ownPain.Id),"Do not draw into fatigue through intellect or own acolyte");
  g=Game();g.Players[0].Health=3;var mirror=g.Summon(1,"VAN_CS2_mirror");Hand(g,"CS2_024");move=AiMove(g);Check(move.Key!="CS2_024"||move.Target.UnitId!=mirror.Id,"Do not spend frostbolt on harmless mirror at low health");
  g=Game();g.Players[0].Health=8;g.Players[0].Mana=5;g.Players[1].ClassId="WARLOCK";g.Players[1].ReportedHandCount=2;g.Summon(1,"VAN_CS2_182").BaseAttack=6;g.Summon(1,"VAN_CS2_182").BaseAttack=3;g.Summon(1,"VAN_CS2_182").BaseAttack=3;Hand(g,"EX1_295");Hand(g,"EX1_289");Check(AiMove(g).Key=="EX1_295","Prefer block to barrier when Zoo can add direct burst to visible lethal");
  g=Game();g.Players[0].Health=1;g.Players[0].Fatigue=2;g.Players[0].Deck.Clear();g.Players[0].Deck.Add("VAN_CS2_031");Hand(g,"CS2_023");Check(AiMove(g).Key!="CS2_023","Do not take lethal fatigue from overdraw beyond remaining deck");
  g=Game();g.Players[0].Health=4;for(int n=0;n<7;n++)g.Summon(1,"VAN_EX1_020").Windfury=true;g.Summon(0,"VAN_CS2_mirror");g.Summon(0,"VAN_CS2_mirror");foreach(string key in new[]{"CS2_026","CS2_028","CS2_032","CS2_031","CS2_024","CS2_029","EX1_295","EX1_289","NEW1_021"})Hand(g,key);watch=Stopwatch.StartNew();AiMove(g,ai);watch.Stop();Check(ai.LastDefenseNodes<=FreezeMageDefense.NodeLimit&&watch.ElapsedMilliseconds<1000,"Wide shield and windfury board bounded defense search");
